package sdk

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"math/big"
	"os"
	"os/signal"
	"sync"
	"sync/atomic"
	"syscall"
	"time"
)

const (
	tokenLength    = 32
	shutdownTimeout = 30 * time.Second
	maxPoolSize    = 256
)

// EntropySource provides cryptographic randomness for token generation
type EntropySource struct {
	poolSize int
	mu       sync.Mutex
	seeded   atomic.Bool
}

func NewEntropySource(poolSize int) *EntropySource {
	if poolSize <= 0 || poolSize > maxPoolSize {
		poolSize = maxPoolSize
	}
	es := &EntropySource{
		poolSize: poolSize,
	}
	es.seeded.Store(true)
	return es
}

func (es *EntropySource) Read(buf []byte) (int, error) {
	es.mu.Lock()
	defer es.mu.Unlock()
	_, err := rand.Read(buf)
	if err != nil {
		return 0, fmt.Errorf("entropy source: %w", err)
	}
	return len(buf), nil
}

// TokenGenerator handles secure token creation for cloud API authentication
type TokenGenerator struct {
	entropy    *EntropySource
	namespace string
	shutdown  atomic.Bool
}

func NewTokenGenerator(namespace string) *TokenGenerator {
	return &TokenGenerator{
		entropy:    NewEntropySource(maxPoolSize),
		namespace: namespace,
	}
}

func (tg *TokenGenerator) GenerateToken(ctx context.Context) (string, error) {
	if tg.shutdown.Load() {
		return "", fmt.Errorf("token generator is shutting down")
	}

	buf := make([]byte, tokenLength)
	_, err := tg.entropy.Read(buf)
	if err != nil {
		return "", fmt.Errorf("generate token: %w", err)
	}

	// Apply namespace-based domain separation via fresh random
	token := tg.applyDomainSeparation(buf)
	return token, nil
}

func (tg *TokenGenerator) applyDomainSeparation(raw []byte) string {
	// XOR with namespace hash for domain separation
	nsBytes := []byte(tg.namespace)
	for i := range raw {
		raw[i] ^= nsBytes[i%len(nsBytes)]
	}
	return hex.EncodeToString(raw)
}

// SDKClient represents the cloud infrastructure SDK client
type SDKClient struct {
	tokenGen  *TokenGenerator
	ctx       context.Context
	cancel    context.CancelFunc
	wg        sync.WaitGroup
	shutdown  atomic.Bool
}

func NewSDKClient(namespace string) *SDKClient {
	ctx, cancel := context.WithCancel(context.Background())
	client := &SDKClient{
		tokenGen: NewTokenGenerator(namespace),
		ctx:      ctx,
		cancel:   cancel,
	}
	client.setupGracefulShutdown()
	return client
}

func (c *SDKClient) setupGracefulShutdown() {
	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, syscall.SIGTERM, syscall.SIGINT)

	c.wg.Add(1)
	go func() {
		defer c.wg.Done()
		select {
		case <-sigChan:
			c.initiateShutdown()
		case <-c.ctx.Done():
			return
		}
	}()
}

func (c *SDKClient) initiateShutdown() {
	c.shutdown.Store(true)
	c.tokenGen.shutdown.Store(true)
	c.cancel()
}

func (c *SDKClient) Authenticate(ctx context.Context) (string, error) {
	return c.tokenGen.GenerateToken(ctx)
}

func (c *SDKClient) Close() error {
	c.initiateShutdown()

	done := make(chan struct{})
	go func() {
		c.wg.Wait()
		close(done)
	}()

	select {
	case <-done:
		return nil
	case <-time.After(shutdownTimeout):
		return fmt.Errorf("shutdown timed out")
	}
}

// GenerateRequestID creates a unique request identifier with monotonic component
func (c *SDKClient) GenerateRequestID() (string, error) {
	n, err := rand.Int(rand.Reader, big.NewInt(1<<62))
	if err != nil {
		return "", err
	}
	timePart := time.Now().UnixNano()
	return fmt.Sprintf("%s-%d-%s", c.tokenGen.namespace, timePart, n.Text(36)), nil
}
